import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Release deployment and disaster recovery (maintainer guide)","description":"","frontmatter":{},"headers":[],"relativePath":"release/disaster-recovery.md","filePath":"release/disaster-recovery.md"}'),n={name:"release/disaster-recovery.md"};function r(i,e,d,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="release-deployment-and-disaster-recovery-maintainer-guide" tabindex="-1">Release deployment and disaster recovery (maintainer guide) <a class="header-anchor" href="#release-deployment-and-disaster-recovery-maintainer-guide" aria-label="Permalink to &quot;Release deployment and disaster recovery (maintainer guide)&quot;">​</a></h1><p>How artifacts reach the world, how the working environment is rebuilt after a sandbox reset, and how to push when the sandbox&#39;s egress breaks. Companion pages: <a href="./process.html">process</a> (the SOP), <a href="./ci-gates.html">ci-gates</a> (the gates), <a href="./website-update.html">website-update</a> and <a href="./wiki-sync.html">wiki-sync</a> (the two sync mechanics in depth).</p><h2 id="_1-the-deployment-surface" tabindex="-1">1. The deployment surface <a class="header-anchor" href="#_1-the-deployment-surface" aria-label="Permalink to &quot;1. The deployment surface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Content</th><th>Mechanism</th></tr></thead><tbody><tr><td>GitHub repo <code>main</code></td><td>source of truth</td><td>git push (or the API replay channel, §6)</td></tr><tr><td>GitHub Releases</td><td>ISO + src zip + OTA tar.gz + note with the three SHA256s</td><td>Release UI / API from the tagged, CI-green commit</td></tr><tr><td><code>gh-pages</code> branch</td><td>the website: facade + docs center + OTA manifests</td><td><code>website/build.sh</code> output pushed to the branch</td></tr><tr><td>Custom domain</td><td><code>ocos.cubestudio.cn</code></td><td>CNAME in the deploy root (GitHub Pages cname)</td></tr><tr><td>GitHub Wiki</td><td>curated bilingual docs view</td><td><code>tools/sync_wiki.sh</code></td></tr><tr><td>Private mirror</td><td>assets + release note + mirrored website files + audit docs</td><td>repo-to-repo copy (below)</td></tr></tbody></table><h2 id="_2-two-repo-synchronization-rules" tabindex="-1">2. Two-repo synchronization rules <a class="header-anchor" href="#_2-two-repo-synchronization-rules" aria-label="Permalink to &quot;2. Two-repo synchronization rules&quot;">​</a></h2><p>The project keeps a public repo (<code>cubestudio-dev/OpenCubeOS</code>) and a private mirror. The mirror rules (the canonical statement is <a href="./process.html">process</a> §7 + the mirror&#39;s own SYNC-RULES.md):</p><ol><li><strong>What syncs</strong>: the three release assets, the release note, the mirrored website files, and repo-level audit documents (postcheck reports, work log). The mirror is the audit trail of record — a full postcheck is archived there per release.</li><li><strong>What does NOT sync</strong>: build products (<code>build/</code>, <code>dist/</code>, <code>iso/</code>, <code>releases/</code>) and the website build trees (<code>website/out</code>, <code>website/.next</code>, <code>website/node_modules</code>, <code>website/public/downloads</code>) — the same exclusion philosophy the <code>Makefile</code> <code>SRC_EXCLUDE</code> applies to the source zip. The mirror holds sources, evidence and assets, never transient build state. Website <em>outputs</em> reach users via gh-pages, not via the mirror.</li><li><strong>Gate</strong>: <code>git ls-remote</code> on BOTH repos shows the expected HEADs (12-point check item 1; see <a href="./ci-gates.html">ci-gates</a> §4). Assets restored into the mirror are SHA-verified against the Release (the 2.0.0 assets were re-fetched from a Release and hash-verified this way).</li><li><strong>Byte-identity promise</strong>: the Release, gh-pages downloads and the mirror hold byte-identical copies of each asset (P-11 lesson: the public main tree must also carry them under <code>website/public/downloads/</code>).</li></ol><h2 id="_3-sandbox-reset-—-the-standard-recovery-procedure" tabindex="-1">3. Sandbox reset — the standard recovery procedure <a class="header-anchor" href="#_3-sandbox-reset-—-the-standard-recovery-procedure" aria-label="Permalink to &quot;3. Sandbox reset — the standard recovery procedure&quot;">​</a></h2><p>The canonical sandbox layout (the one the tooling assumes): <code>/home/z/ocos</code> = the repo, <code>/home/z/opt/extract</code> = the relocated toolchain, <code>$HOME/.cache/opencube-cc</code> = the compile cache. After a sandbox reset, rebuild the environment in this order:</p><ol><li><strong>Restore the repo</strong> — clone (or re-play from a bundle, §5) to <code>/home/z/ocos</code>. Confirm the working tree is clean and on the expected branch; the build id derivation needs the full history (<code>git rev-list --count HEAD</code>), so never restore a shallow copy.</li><li><strong>Unpack the toolchain (no root needed)</strong> — <code>bash tools/install-toolchain.sh</code>: downloads the Debian .debs in three batches (build tools / qemu / grub+firmware, ~117 packages including dependencies) and <code>dpkg -x</code>-extracts them into <code>$OC_OPT</code> (default <code>/home/z/opt/extract</code>): nasm 2.16.03, qemu-system-x86 10.0.13 (+ data + libs), xorriso 1.5.6, grub-pc-bin + grub-efi-amd64-bin + grub-common, mtools, ovmf, seabios. gcc itself comes from the system (Debian gcc 14.2.0 is the release compiler).</li><li><strong>Source the environment</strong> — <code>source tools/env-sandbox.sh</code> (the repo&#39;s sandbox environment script): exports <code>OC_TOOLS=/home/z/opt/extract</code>, prepends <code>$OC_TOOLS/usr/bin</code> to PATH, and sets <code>LD_LIBRARY_PATH</code> to the extract&#39;s lib dirs (the relocated QEMU needs them). Every QEMU-driving tool also honors <code>OC_TOOLS</code>.</li><li><strong>QEMU/OVMF placement check</strong> — <code>OVMF_FD</code> defaults to <code>$(OC_TOOLS)/share/ovmf/OVMF.fd</code>, <code>QEMU_DATADIR</code> to <code>$(OC_TOOLS)/share/qemu</code>, <code>SEABIOS_DIR</code> to <code>$(OC_TOOLS)/share/seabios</code>. Verify with <code>make run-bios</code> on the freshly built ISO; if the runner&#39;s OVMF build needs the split pflash pair, <code>OVMF_CODE_4M.fd</code> + <code>OVMF_VARS_4M.fd</code> are used by <code>build_release.sh</code>&#39;s UEFI gate (plain <code>-bios</code> silently fails to run the payload on current OVMF builds).</li><li><strong>Evidence baseline</strong> — restore/rebuild <code>evidence/</code> captures the gates consume: <code>evidence/help_a_runtime.txt</code> (the runtime <code>help -a</code> capture behind <code>make api-docs</code>) and the release gate logs. Then run the cheap verification ladder: <code>make clean &amp;&amp; make all</code> (0-warning gate) → <code>make reproducible-check</code> → <code>make run-bios</code> / <code>make run-uefi</code> banner gates. A full recovery is proven by <code>tools/build_release.sh &lt;ver&gt; --deep</code> passing end to end.</li><li><strong>Compile cache</strong> — optional; wipe or keep <code>~/.cache/opencube-cc</code> (<code>make cache-clear</code>); hits are byte-identical so the cache never invalidates a gate.</li></ol><h2 id="_4-website-update-flow" tabindex="-1">4. Website update flow <a class="header-anchor" href="#_4-website-update-flow" aria-label="Permalink to &quot;4. Website update flow&quot;">​</a></h2><p><code>website/build.sh</code> (run as the last <code>build_release.sh</code> step, after <code>tools/update_website.sh</code> has written the release numbers):</p><ol><li>Installs docs-center dependencies once (<code>npm install</code> → vitepress).</li><li>Syncs the repo <code>docs/</code> tree into the build-time copy <code>docs-src/docs/</code> via <code>rsync -a --delete</code> (excluding <code>archive/</code> and <code>data/</code>) — the repository docs/ is the single source of truth; the copy is git-ignored.</li><li>Builds the docs center (<code>npm run docs:build</code>; VitePress, EN root + <code>zh/</code> locale, per-locale search indexes; ~642 pages, 777 on the WP-l1apps-merge full rebuild).</li><li>Assembles the deploy root <code>out/</code>: facade pages (<code>index/architecture/download/about.html</code>), <code>assets/</code>, <code>out/docs/</code>, plus the three deploy-critical files the hard way: <ul><li><code>out/CNAME</code> — content <code>ocos.cubestudio.cn</code> (custom domain; previously only on the gh-pages branch, so a full-tree redeploy could silently drop it — WP06d-site_fix),</li><li><code>out/.nojekyll</code> — empty; stops GitHub Pages from running Jekyll over the VitePress output,</li><li><code>out/update.json</code> + <code>out/update-v2.json</code> — the OTA manifests written by <code>update_website.sh</code> (release-managed content), copied so the kernel&#39;s checkupdate and the download-page footer link never 404.</li></ul></li><li>The <code>out/</code> tree is committed to <code>gh-pages</code> and pushed (§5–§6 for the channel). Pages rebuilds; verify online (allow a minute): the docs center, a known deep page (byte-compare with the local build), and the facade&#39;s version marker. The only tolerated live-vs-local difference is the CDN&#39;s email-obfuscation injection.</li></ol><p><code>update_website.sh &lt;ver&gt; &lt;build&gt; [date] [changes]</code> must run BEFORE the build: it reads the dist assets and writes <code>website/assets/site-data.js</code> + <code>website/update.json</code> + <code>update-v2.json</code> — nothing on the site is hand-edited (details in <a href="./website-update.html">website-update</a>).</p><h2 id="_5-wiki-synchronization" tabindex="-1">5. Wiki synchronization <a class="header-anchor" href="#_5-wiki-synchronization" aria-label="Permalink to &quot;5. Wiki synchronization&quot;">​</a></h2><p><code>tools/sync_wiki.sh [--dry-run]</code> (env: <code>GH_TOKEN</code> with wiki push rights) maps <code>docs/</code> + <code>docs/zh/</code> onto the GitHub Wiki (<code>cubestudio-dev/OpenCubeOS.wiki.git</code>):</p><ul><li>Chinese is the canonical page under the mapped name; English ships as <code>&lt;Page&gt;-EN.md</code>; every page carries a language banner linking to its counterpart.</li><li>The <code>map_page()</code> table is the contract: ~83 mapped Wiki page names (Home, Getting-Started, Mega-Apps, Boot-Modes, Shell-Basics, Filesystems, Networking, Update-and-OTA, TUI-Guide, Chinese-Console, Recovery, User-Manual, Command-Reference, Building-from-Source, Architecture-<em>, L1-</em>, Drivers-<em>, Internals-</em>, Troubleshooting-*, Versioning, Release-Process, …) plus the <code>Release-Notes = GENERATED</code> sentinel. Pages NOT in the table are reachable only through the docs center — the Wiki is the curated view, the docs center is the full tree.</li><li>Links are rewritten to <code>[[Wiki-Links]]</code> per language (zh → canonical names, en → <code>-EN</code>-suffixed), directory links collapse to the section index page, anchors are dropped (zh headings are localized), relative assets are stripped.</li><li>Runs at release time after docs/ changes land, and on demand for docs-only updates. Verification: every mapped page exists, no red links among the mapped set, and the script diffs Wiki vs docs before pushing (see <a href="./wiki-sync.html">wiki-sync</a>).</li></ul><h2 id="_6-the-restricted-egress-push-channel-api-github-com-replay" tabindex="-1">6. The restricted-egress push channel (api.github.com replay) <a class="header-anchor" href="#_6-the-restricted-egress-push-channel-api-github-com-replay" aria-label="Permalink to &quot;6. The restricted-egress push channel (api.github.com replay)&quot;">​</a></h2><p><strong>The failure</strong>: in the release sandbox, <code>git push</code> over smart-HTTP persistently dies with a GnuTLS error (-110, the connection-terminated / TLS record overflow class). The <code>git</code> channel is therefore unusable exactly when a release must ship.</p><p><strong>First-line workaround</strong> (keeps using git where possible): <code>deploy_with_token.sh &lt;GH_TOKEN&gt;</code> — a fresh <code>git init</code> scratch repo, <code>git config http.version HTTP/1.1</code>, fetch the remote base refs, fetch the prepared commits from thin <code>*.bundle</code> files (bundles carry ONLY the new commits; prerequisites = the current remote tips, so the pushes are fast-forwards), push <code>main</code> + <code>gh-pages</code>, then PATCH the Release body via the REST API. Requires no local clone of the repo. When even this push dies (the observed case), fall through to:</p><p><strong>The API replay channel — <code>api_push3.py</code></strong> (hierarchical chunk-accumulation tree builder over the Git Data API):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 api_push3.py &lt;repo-path&gt; &lt;slug&gt; &lt;token&gt; &lt;branch&gt; &lt;base&gt; &lt;head&gt; \\</span></span>
<span class="line"><span>    [--threads 6] [--chunk 400] [--state file.tsv]</span></span></code></pre></div><p>Why it exists (both alternatives fail):</p><ul><li>a FLAT full-tree POST is 422-rejected by GitHub on ~2600-entry payloads (&quot;request timed out / input too large&quot;) — non-retryable;</li><li><code>base_tree</code> + null-sha deletions silently KEEP the null-sha entries (observed in the wiki/deploy work).</li></ul><p>How it works per commit being replayed:</p><ol><li><strong>Base verification first</strong>: the remote branch head&#39;s tree SHA must equal the local <code>&lt;base&gt;</code> tree SHA — a mismatch aborts with <code>FATAL: ... replay base mismatch</code> (exit 2) so the replay can never land on top of an unknown remote state.</li><li><strong>Threaded blob upload</strong> for changed files: skip when the content SHA already exists anywhere in the remote tree; POST <code>/git/blobs</code> (base64) otherwise; verify the returned SHA equals the local one (<code>blob sha drift</code> is fatal); progress and completion are appended to a <code>--state</code> TSV under a lock — the resumable checkpoint after an interruption.</li><li><strong>Dirty-dirtree rebuild, deepest first</strong>: each dirty directory is rebuilt from its FINAL children set in ≤ <code>--chunk</code> (default 400) accumulation passes (first pass plain, later passes <code>base_tree=&lt;prev&gt; + next chunk</code>). Deletions never appear because the child set is final. <strong>Every directory&#39;s resulting tree SHA is hard-verified against the local git tree SHA</strong> — any level mismatch aborts (<code>FATAL: dir &#39;&lt;d&gt;&#39; tree &lt;sha&gt; != local &lt;sha&gt;</code>, exit 3).</li><li><strong>Root tree verified == the local commit&#39;s tree SHA</strong>, then the commit is created with preserved author + committer (name, email, ISO dates — a bit-exact replay when the parent chain matches).</li><li><strong>Ref update</strong>: <code>PATCH /git/refs/heads/&lt;branch&gt;</code> with <code>force: false</code> — fast-forward only. Retry policy: 502/503/504/429 retried with backoff, everything else fatal with the response body.</li></ol><p>Known pitfalls (all fixed or documented in the tool):</p><ul><li>the ~2600-entry whole-tree POST → 422 (api_push2.py, the flat version, is kept only as an archive of this failure);</li><li>the print lock was not re-entrant → a nested log call inside a worker thread deadlocked the whole run; now an <code>RLock</code>;</li><li>interrupted runs resume from the state file — never delete it mid-run, and always re-run with the same <code>--state</code> path.</li></ul><p>Recorded usage (the WP-l1apps-merge close-out, 2026-11-15): both <code>main</code> (tree <code>e964148f</code>) and <code>gh-pages</code> (tree <code>3cd102cb</code>) were replayed this way and verified online — docs center, mega-apps page, release page byte-identical with local builds; screenshots archived under the deploy kit&#39;s <code>online-proof/</code>.</p><h2 id="_7-the-persistent-disaster-recovery-directory" tabindex="-1">7. The persistent disaster-recovery directory <a class="header-anchor" href="#_7-the-persistent-disaster-recovery-directory" aria-label="Permalink to &quot;7. The persistent disaster-recovery directory&quot;">​</a></h2><p>The sandbox resets; some things must outlive it. Convention: a <code>download/</code> directory that is NOT part of the sandbox&#39;s reset scope holds the release-survival kit:</p><ul><li><strong>Bundles</strong>: <code>main-new.bundle</code> / <code>gh-pages-new.bundle</code> — thin git bundles carrying only the new commits. If the remote baseline has not moved, they are directly re-playable (<code>git fetch &lt;bundle&gt; &lt;branch&gt;</code> then push, or the deploy script&#39;s flow).</li><li><strong>The deploy scripts themselves</strong>: <code>deploy_with_token.sh</code> (git channel), <code>api_push2.py</code> (flat-tree archive), <code>api_push3.py</code> (the working channel).</li><li><strong>State + logs</strong>: <code>state-*.tsv</code> (blob resume checkpoints), <code>push-*.log</code> (execution logs) — keep them with the tooling that wrote them.</li><li><strong>The release body</strong>: <code>release-body.md</code> — the exact note text, so a Release can be re-created or re-PATCHed without reconstructing it.</li><li><strong>Evidence</strong>: <code>online-proof/</code> screenshots and <code>preview-*.png</code> — the &quot;it is live&quot; record for the delivery report.</li></ul><p>Rules of the directory: it mirrors only what the release chain produces (assets live in Releases/gh-pages, not here); every file is re-creatable from the repo + the Release, but keeping it turns a 2-hour recovery into a 10-minute one. After each release, refresh the kit (new bundles if commits moved, new state files, new proof) and prune anything older than the last two releases.</p><h2 id="_8-recovery-checklist-one-page" tabindex="-1">8. Recovery checklist (one page) <a class="header-anchor" href="#_8-recovery-checklist-one-page" aria-label="Permalink to &quot;8. Recovery checklist (one page)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># environment</span></span>
<span class="line"><span>bash tools/install-toolchain.sh          # once; $OC_OPT=/home/z/opt/extract</span></span>
<span class="line"><span>source tools/env-sandbox.sh              # OC_TOOLS + PATH + LD_LIBRARY_PATH</span></span>
<span class="line"><span></span></span>
<span class="line"><span># prove the tree</span></span>
<span class="line"><span>cd /home/z/ocos &amp;&amp; git status            # clean, full history</span></span>
<span class="line"><span>make clean &amp;&amp; make -j all                # 0-warning gate</span></span>
<span class="line"><span>make reproducible-check                  # byte-identical ELF</span></span>
<span class="line"><span>make run-bios &amp;&amp; make run-uefi           # banner gates</span></span>
<span class="line"><span></span></span>
<span class="line"><span># release data + site</span></span>
<span class="line"><span>tools/update_website.sh &lt;ver&gt; &lt;build&gt; &lt;date&gt;</span></span>
<span class="line"><span>website/build.sh                         # out/ = deploy root</span></span>
<span class="line"><span></span></span>
<span class="line"><span># push (pick the channel that works)</span></span>
<span class="line"><span>git push origin main                     # normal</span></span>
<span class="line"><span>./deploy_with_token.sh $GH_TOKEN         # bundle + HTTP/1.1 + API PATCH</span></span>
<span class="line"><span>python3 api_push3.py &lt;repo&gt; &lt;slug&gt; $GH_TOKEN main &lt;base&gt; &lt;head&gt; --state s.tsv</span></span>
<span class="line"><span></span></span>
<span class="line"><span># verify</span></span>
<span class="line"><span>tools/sync_wiki.sh</span></span>
<span class="line"><span># ...then the 12-point check (ci-gates.md §4)</span></span></code></pre></div>`,35)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
